1	// Package indexroom implements chain ingestion with reorg handling.
2	package indexroom
3	
4	import "sort"
5	
6	// Block is one ingested block with its transactions.
7	type Block struct {
8		Height int64
9		Hash   string
10		Parent string
11		Txs    []string
12	}
13	
14	// Index is the durable chain view.
15	type Index struct {
16		Blocks map[int64]Block
17		ByHash map[string]int64
18		Tip    int64
19	}
20	
21	// New returns an empty index.
22	func New() *Index { return &Index{Blocks: map[int64]Block{}, ByHash: map[string]int64{}} }
23	
24	// Append accepts a block only when it extends the current tip, keeping the chain linear.
25	func (index *Index) Append(block Block) error {
26		if block.Height <= 0 || block.Hash == "" {
27			return errInvalid("block needs a height and hash")
28		}
29		if _, exists := index.Blocks[block.Height]; exists {
30			return errInvalid("height already indexed")
31		}
32		if index.Tip != 0 && block.Parent != index.Blocks[index.Tip].Hash {
33			return errInvalid("parent does not match the current tip")
34		}
35		index.Blocks[block.Height] = block
36		index.ByHash[block.Hash] = block.Height
37		index.Tip = block.Height
38		return nil
39	}
40	
41	// Reorg replaces the tip range with an alternate branch and reports dropped heights.
42	func (index *Index) Reorg(blocks []Block) ([]int64, error) {
43		if len(blocks) == 0 {
44			return nil, errInvalid("empty branch")
45		}
46		parent, ok := index.ByHash[blocks[0].Parent]
47		if !ok {
48			return nil, errInvalid("branch parent is unknown")
49		}
50		var dropped []int64
51		for height := parent + 1; height <= index.Tip; height++ {
52			dropped = append(dropped, height)
53			delete(index.ByHash, index.Blocks[height].Hash)
54			delete(index.Blocks, height)
55		}
56		index.Tip = parent
57		for _, block := range blocks {
58			if err := index.Append(block); err != nil {
59				return dropped, err
60			}
61		}
62		sort.Slice(dropped, func(i, j int) bool { return dropped[i] < dropped[j] })
63		return dropped, nil
64	}
65	
66	type errInvalid string
67	
68	func (e errInvalid) Error() string { return string(e) }
