1	// Package indexroom implements chain ingestion with reorg handling.
2	package indexroom
3	
4	import (
5		"fmt"
6		"net"
7		"sort"
8		"strconv"
9		"strings"
10		"unicode"
11	)
12	
13	// Instance is one discoverable service instance.
14	type Instance struct {
15		ID      string
16		Address string
17	}
18	
19	// HealthState is the offline health observation of one instance.
20	// Health is driven entirely by submitted observations; no probing occurs.
21	type HealthState string
22	
23	// Health states.
24	const (
25		HealthUnknown   HealthState = "unknown"
26		HealthHealthy   HealthState = "healthy"
27		HealthUnhealthy HealthState = "unhealthy"
28	)
29	
30	// InstanceView is a snapshot of one instance together with its health observation.
31	type InstanceView struct {
32		ID       string
33		Address  string
34		Health   HealthState
35		Sequence int64
36		Reason   string
37	}
38	
39	// Registration is a validated request that replaces a service's instance list.
40	type Registration struct {
41		Service   string
42		Revision  int
43		Instances []Instance
44	}
45	
46	// HealthUpdate is a validated health observation request.
47	type HealthUpdate struct {
48		Service    string
49		InstanceID string
50		Revision   int
51		Sequence   int64
52		Healthy    bool
53		Reason     string
54	}
55	
56	// ServiceView is an immutable snapshot of one registered service.
57	type ServiceView struct {
58		Service   string
59		Revision  int
60		Instances []InstanceView
61	}
62	
63	// OutcomeKind classifies a failed request.
64	type OutcomeKind string
65	
66	// Outcome kinds.
67	const (
68		OutcomeInvalid   OutcomeKind = "invalid"
69		OutcomeConflict  OutcomeKind = "conflict"
70		OutcomeNotFound  OutcomeKind = "not_found"
71		OutcomeStale     OutcomeKind = "stale"
72		OutcomeNoHealthy OutcomeKind = "no_healthy"
73	)
74	
75	// Outcome is the result of applying one registration against the registry.
76	type Outcome struct {
77		Service  string
78		OK       bool
79		Changed  bool
80		Revision int
81		Kind     OutcomeKind
82		Reason   string
83		Expected int
84		Actual   int
85	}
86	
87	// HealthOutcome is the result of applying one health update against the registry.
88	type HealthOutcome struct {
89		Service    string
90		InstanceID string
91		OK         bool
92		Changed    bool
93		Kind       OutcomeKind
94		Reason     string
95		Revision   int
96		Expected   int
97		Actual     int
98		Sequence   int64
99	}
100	
101	// Selection is a validated request that chooses one healthy target instance.
102	type Selection struct {
103		Service  string
104		Revision int
105	}
106	
107	// SelectOutcome is the result of choosing one healthy instance.
108	//
109	// On success the chosen instance carries its id, address and current health
110	// sequence. A selection never mutates registrations, health records or the
111	// per-service rotation cursor on failure; on success it only advances that
112	// cursor to the chosen instance's id.
113	type SelectOutcome struct {
114		Service    string
115		OK         bool
116		Kind       OutcomeKind
117		Reason     string
118		Revision   int
119		Expected   int
120		Actual     int
121		InstanceID string
122		Address    string
123		Sequence   int64
124	}
125	
126	// Registry is an in-memory service instance registry.
127	type Registry struct {
128		services map[string]*serviceState
129	}
130	
131	type serviceState struct {
132		revision  int
133		instances map[string]*instanceState // instance id -> state
134	
135		// cursor is the id returned by the last successful selection. Selection
136		// starts at the smallest healthy id before any success (cursorSet == false)
137		// and otherwise continues just after cursor. The cursor intentionally
138		// survives registration replacements and health changes: removed instances
139		// and recovered or newly joined instances are located by id in the current
140		// healthy set without restarting the rotation.
141		cursor    string
142		cursorSet bool
143	}
144	
145	type instanceState struct {
146		address  string
147		health   HealthState
148		sequence int64
149		reason   string
150	}
151	
152	// newInstanceState returns a fresh observation: unknown with sequence 0.
153	func newInstanceState(address string) *instanceState {
154		return &instanceState{address: address, health: HealthUnknown}
155	}
156	
157	// NewRegistry returns an empty registry.
158	func NewRegistry() *Registry {
159		return &Registry{services: map[string]*serviceState{}}
160	}
161	
162	// RevisionOf returns the service's current revision, or 0 when it is unknown.
163	func (r *Registry) RevisionOf(service string) int {
164		if st, ok := r.services[service]; ok {
165			return st.revision
166		}
167		return 0
168	}
169	
170	// ValidateRegistration trims and validates one request without mutating the registry.
171	// Content validity is established before any revision check.
172	func (r *Registry) ValidateRegistration(service string, revision int, instances []Instance) (Registration, error) {
173		name := strings.TrimSpace(service)
174		if name == "" {
175			return Registration{}, errInvalid("service name must not be empty")
176		}
177		if revision < 0 {
178			return Registration{}, errInvalid("expectedRevision must be a non-negative integer")
179		}
180		seen := make(map[string]bool, len(instances))
181		valid := make([]Instance, 0, len(instances))
182		for _, inst := range instances {
183			id := strings.TrimSpace(inst.ID)
184			if id == "" {
185				return Registration{}, errInvalid("instance id must not be empty")
186			}
187			if seen[id] {
188				return Registration{}, errInvalid(fmt.Sprintf("duplicate instance id %q", id))
189			}
190			addr, err := parseAddress(inst.Address)
191			if err != nil {
192				return Registration{}, errInvalid(err.Error())
193			}
194			seen[id] = true
195			valid = append(valid, Instance{ID: id, Address: addr})
196		}
197		return Registration{Service: name, Revision: revision, Instances: valid}, nil
198	}
199	
200	// Apply checks the revision and, on match, replaces the service's instance list.
201	// A new service is created at revision 1 only when expectedRevision is 0.
202	// A matching registration with identical content succeeds without bumping revision.
203	func (r *Registry) Apply(reg Registration) Outcome {
204		st, exists := r.services[reg.Service]
205		if !exists {
206			if reg.Revision != 0 {
207				return Outcome{
208					Service:  reg.Service,
209					OK:       false,
210					Kind:     OutcomeConflict,
211					Reason:   fmt.Sprintf("service %q does not exist yet; expected revision must be 0, got %d", reg.Service, reg.Revision),
212					Expected: reg.Revision,
213					Actual:   0,
214					Revision: 0,
215				}
216			}
217			st = &serviceState{revision: 1, instances: make(map[string]*instanceState, len(reg.Instances))}
218			r.services[reg.Service] = st
219			for _, inst := range reg.Instances {
220				st.instances[inst.ID] = newInstanceState(inst.Address)
221			}
222			return Outcome{Service: reg.Service, OK: true, Changed: true, Revision: 1}
223		}
224		if reg.Revision != st.revision {
225			return Outcome{
226				Service:  reg.Service,
227				OK:       false,
228				Kind:     OutcomeConflict,
229				Reason:   fmt.Sprintf("service %q is at revision %d, not %d", reg.Service, st.revision, reg.Revision),
230				Expected: reg.Revision,
231				Actual:   st.revision,
232				Revision: st.revision,
233			}
234		}
235		changed := !sameInstances(st.instances, reg.Instances)
236		if changed {
237			// A replacement fully rebuilds the list, but an instance that keeps both
238			// its id and its address retains its health observation. Anything new,
239			// address-changed, or removed-then-readded starts from unknown at sequence 0.
240			next := make(map[string]*instanceState, len(reg.Instances))
241			for _, inst := range reg.Instances {
242				if old, ok := st.instances[inst.ID]; ok && old.address == inst.Address {
243					next[inst.ID] = old
244				} else {
245					next[inst.ID] = newInstanceState(inst.Address)
246				}
247			}
248			st.instances = next
249			st.revision++
250		}
251		return Outcome{Service: reg.Service, OK: true, Changed: changed, Revision: st.revision}
252	}
253	
254	// ValidateHealth trims and validates one health observation without mutating
255	// the registry. Content validity is established before any revision check.
256	func (r *Registry) ValidateHealth(service, instanceID string, revision int, sequence int64, healthy bool, reason string) (HealthUpdate, error) {
257		name := strings.TrimSpace(service)
258		if name == "" {
259			return HealthUpdate{}, errInvalid("service name must not be empty")
260		}
261		id := strings.TrimSpace(instanceID)
262		if id == "" {
263			return HealthUpdate{}, errInvalid("instance id must not be empty")
264		}
265		if revision < 0 {
266			return HealthUpdate{}, errInvalid("expectedRevision must be a non-negative integer")
267		}
268		if sequence <= 0 {
269			return HealthUpdate{}, errInvalid("sequence must be a positive integer")
270		}
271		normalizedReason := strings.TrimSpace(reason)
272		if healthy {
273			// A healthy observation carries no reason.
274			normalizedReason = ""
275		} else if normalizedReason == "" {
276			return HealthUpdate{}, errInvalid("reason must not be empty when unhealthy")
277		}
278		return HealthUpdate{
279			Service:    name,
280			InstanceID: id,
281			Revision:   revision,
282			Sequence:   sequence,
283			Healthy:    healthy,
284			Reason:     normalizedReason,
285		}, nil
286	}
287	
288	// ApplyHealth checks the revision and records an offline observation.
289	//
290	// The revision is checked first: a mismatch is a conflict carrying the request
291	// and current revisions, even when the instance exists. With a matching
292	// revision, a missing service or instance is not_found. Sequence handling:
293	//   - a sequence below the accepted one is stale and reports the current sequence;
294	//   - the same sequence with identical normalized status and reason succeeds
295	//     without changing state;
296	//   - the same sequence with different content is a conflict;
297	//   - a newer sequence writes the status and reason.
298	func (r *Registry) ApplyHealth(upd HealthUpdate) HealthOutcome {
299		st, exists := r.services[upd.Service]
300		actual := 0
301		if exists {
302			actual = st.revision
303		}
304		if upd.Revision != actual {
305			return HealthOutcome{
306				Service:  upd.Service,
307				OK:       false,
308				Kind:     OutcomeConflict,
309				Reason:   fmt.Sprintf("service %q is at revision %d, not %d", upd.Service, actual, upd.Revision),
310				Expected: upd.Revision,
311				Actual:   actual,
312				Revision: actual,
313			}
314		}
315		if !exists {
316			return HealthOutcome{
317				Service:  upd.Service,
318				OK:       false,
319				Kind:     OutcomeNotFound,
320				Reason:   fmt.Sprintf("service %q does not exist", upd.Service),
321				Revision: 0,
322			}
323		}
324		cur, ok := st.instances[upd.InstanceID]
325		if !ok {
326			return HealthOutcome{
327				Service:    upd.Service,
328				InstanceID: upd.InstanceID,
329				OK:         false,
330				Kind:       OutcomeNotFound,
331				Reason:     fmt.Sprintf("instance %q does not exist in service %q", upd.InstanceID, upd.Service),
332				Revision:   st.revision,
333			}
334		}
335		if upd.Sequence < cur.sequence {
336			return HealthOutcome{
337				Service:    upd.Service,
338				InstanceID: upd.InstanceID,
339				OK:         false,
340				Kind:       OutcomeStale,
341				Reason:     fmt.Sprintf("sequence %d is older than the current sequence %d", upd.Sequence, cur.sequence),
342				Revision:   st.revision,
343				Sequence:   cur.sequence,
344			}
345		}
346		if upd.Sequence == cur.sequence {
347			want := HealthUnhealthy
348			if upd.Healthy {
349				want = HealthHealthy
350			}
351			if cur.health == want && cur.reason == upd.Reason {
352				return HealthOutcome{
353					Service:    upd.Service,
354					InstanceID: upd.InstanceID,
355					OK:         true,
356					Changed:    false,
357					Revision:   st.revision,
358					Sequence:   cur.sequence,
359				}
360			}
361			return HealthOutcome{
362				Service:    upd.Service,
363				InstanceID: upd.InstanceID,
364				OK:         false,
365				Kind:       OutcomeConflict,
366				Reason:     fmt.Sprintf("sequence %d already used with different health content", upd.Sequence),
367				Revision:   st.revision,
368				Sequence:   cur.sequence,
369			}
370		}
371		// Newer sequence: record the observation. Health updates never bump the
372		// registration revision.
373		if upd.Healthy {
374			cur.health = HealthHealthy
375			cur.reason = ""
376		} else {
377			cur.health = HealthUnhealthy
378			cur.reason = upd.Reason
379		}
380		cur.sequence = upd.Sequence
381		return HealthOutcome{
382			Service:    upd.Service,
383			InstanceID: upd.InstanceID,
384			OK:         true,
385			Changed:    true,
386			Revision:   st.revision,
387			Sequence:   cur.sequence,
388		}
389	}
390	
391	// ValidateSelection trims and validates one select request without touching
392	// the registry. Content validity is established before any revision check.
393	func (r *Registry) ValidateSelection(service string, revision int) (Selection, error) {
394		name := strings.TrimSpace(service)
395		if name == "" {
396			return Selection{}, errInvalid("service name must not be empty")
397		}
398		if revision < 0 {
399			return Selection{}, errInvalid("expectedRevision must be a non-negative integer")
400		}
401		return Selection{Service: name, Revision: revision}, nil
402	}
403	
404	// Select checks the revision and chooses one healthy instance for the service.
405	//
406	// The revision is checked first: a mismatch is a conflict carrying the request
407	// and current revisions (an unknown service is at revision 0). With a matching
408	// revision, a missing service is not_found. When the service exists but has no
409	// healthy instance the outcome is no_healthy and no address is fabricated.
410	//
411	// Healthy instances rotate per service by ascending instance id: the first
412	// success takes the smallest id and each later success continues just after
413	// the previously chosen id, wrapping to the smallest id past the end. With a
414	// single healthy instance it may be chosen repeatedly. Registrations and
415	// health changes alter the candidate set immediately but never reset the
416	// rotation; failed selections leave the cursor where it was.
417	func (r *Registry) Select(sel Selection) SelectOutcome {
418		st, exists := r.services[sel.Service]
419		actual := 0
420		if exists {
421			actual = st.revision
422		}
423		if sel.Revision != actual {
424			return SelectOutcome{
425				Service:  sel.Service,
426				OK:       false,
427				Kind:     OutcomeConflict,
428				Reason:   fmt.Sprintf("service %q is at revision %d, not %d", sel.Service, actual, sel.Revision),
429				Expected: sel.Revision,
430				Actual:   actual,
431				Revision: actual,
432			}
433		}
434		if !exists {
435			return SelectOutcome{
436				Service:  sel.Service,
437				OK:       false,
438				Kind:     OutcomeNotFound,
439				Reason:   fmt.Sprintf("service %q does not exist", sel.Service),
440				Revision: 0,
441			}
442		}
443	
444		healthy := make([]string, 0, len(st.instances))
445		for id, cur := range st.instances {
446			if cur.health == HealthHealthy {
447				healthy = append(healthy, id)
448			}
449		}
450		sort.Strings(healthy)
451		if len(healthy) == 0 {
452			return SelectOutcome{
453				Service:  sel.Service,
454				OK:       false,
455				Kind:     OutcomeNoHealthy,
456				Reason:   fmt.Sprintf("service %q has no healthy instance available", sel.Service),
457				Revision: st.revision,
458			}
459		}
460	
461		chosen := healthy[0]
462		if st.cursorSet {
463			chosen = healthy[0]
464			for _, id := range healthy {
465				if id > st.cursor {
466					chosen = id
467					break
468				}
469			}
470		}
471		cur := st.instances[chosen]
472		st.cursor = chosen
473		st.cursorSet = true
474		return SelectOutcome{
475			Service:    sel.Service,
476			OK:         true,
477			Revision:   st.revision,
478			InstanceID: chosen,
479			Address:    cur.address,
480			Sequence:   cur.sequence,
481		}
482	}
483	
484	// Snapshot returns all services sorted by name, with instances sorted by id.
485	func (r *Registry) Snapshot() []ServiceView {
486		names := make([]string, 0, len(r.services))
487		for name := range r.services {
488			names = append(names, name)
489		}
490		sort.Strings(names)
491		views := make([]ServiceView, 0, len(names))
492		for _, name := range names {
493			st := r.services[name]
494			ids := make([]string, 0, len(st.instances))
495			for id := range st.instances {
496				ids = append(ids, id)
497			}
498			sort.Strings(ids)
499			instances := make([]InstanceView, 0, len(ids))
500			for _, id := range ids {
501				cur := st.instances[id]
502				instances = append(instances, InstanceView{
503					ID:       id,
504					Address:  cur.address,
505					Health:   cur.health,
506					Sequence: cur.sequence,
507					Reason:   cur.reason,
508				})
509			}
510			views = append(views, ServiceView{Service: name, Revision: st.revision, Instances: instances})
511		}
512		return views
513	}
514	
515	func sameInstances(current map[string]*instanceState, incoming []Instance) bool {
516		if len(current) != len(incoming) {
517			return false
518		}
519		for _, inst := range incoming {
520			if old, ok := current[inst.ID]; !ok || old.address != inst.Address {
521				return false
522			}
523		}
524		return true
525	}
526	
527	// parseAddress validates a host:port address: domains, IPv4 and bracketed IPv6.
528	// No network I/O is performed.
529	func parseAddress(raw string) (string, error) {
530		addr := strings.TrimSpace(raw)
531		if addr == "" {
532			return "", fmt.Errorf("instance address must not be empty")
533		}
534		for _, r := range addr {
535			if unicode.IsSpace(r) || unicode.IsControl(r) {
536				return "", fmt.Errorf("instance address %q must not contain whitespace or control characters", addr)
537			}
538		}
539		host, port, err := net.SplitHostPort(addr)
540		if err != nil {
541			return "", fmt.Errorf("instance address %q is not a host:port address: %v", addr, err)
542		}
543		if host == "" {
544			return "", fmt.Errorf("instance address %q has an empty host", addr)
545		}
546		if !allDigits(port) {
547			return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
548		}
549		n, err := strconv.Atoi(port)
550		if err != nil {
551			return "", fmt.Errorf("instance address %q port %q must be a decimal integer", addr, port)
552		}
553		if n < 1 || n > 65535 {
554			return "", fmt.Errorf("instance address %q port %d is out of range (1-65535)", addr, n)
555		}
556		if strings.HasPrefix(addr, "[") {
557			ip := net.ParseIP(host)
558			if ip == nil || !strings.Contains(host, ":") {
559				return "", fmt.Errorf("instance address %q bracketed host is not a valid IPv6 address", addr)
560			}
561		} else if ip := net.ParseIP(host); ip != nil {
562			if ip.To4() == nil {
563				return "", fmt.Errorf("instance address %q IPv6 addresses must be bracketed", addr)
564			}
565		} else if !isDomainName(host) {
566			return "", fmt.Errorf("instance address %q host %q is not a valid domain, IPv4 or bracketed IPv6", addr, host)
567		}
568		return addr, nil
569	}
570	
571	func allDigits(s string) bool {
572		if s == "" {
573			return false
574		}
575		for _, r := range s {
576			if r < '0' || r > '9' {
577				return false
578			}
579		}
580		return true
581	}
582	
583	// isDomainName validates a dotted hostname with alphanumeric/hyphen labels.
584	func isDomainName(host string) bool {
585		if len(host) > 253 {
586			return false
587		}
588		for _, label := range strings.Split(host, ".") {
589			n := len(label)
590			if n == 0 || n > 63 {
591				return false
592			}
593			if label[0] == '-' || label[n-1] == '-' {
594				return false
595			}
596			for _, r := range label {
597				if r == '-' ||
598					(r >= 'a' && r <= 'z') ||
599					(r >= 'A' && r <= 'Z') ||
600					(r >= '0' && r <= '9') {
601					continue
602				}
603				return false
604			}
605		}
606		return true
607	}
