930		if r := got.Results[4]; r.OK || r.Error != "conflict" ||
931			r.Reason != "sequence 9 already used with different health content" ||
932			r.Sequence != 9 || r.Revision != 1 {
933			t.Fatalf("conflicting recovery attempt: %+v", r)
934		}
935		// The rejected recoveries did not restore eligibility: still no_healthy.
936		if r := got.Results[5]; r.OK || r.Error != "no_healthy" || r.Revision != 1 || r.InstanceID != "" || r.Address != "" {
937			t.Fatalf("rejected recoveries must not restore eligibility: %+v", r)
938		}
939		// A higher sequence is accepted and flips the instance to healthy.
940		if r := got.Results[6]; !r.OK || !r.Changed || r.Sequence != 10 || r.Revision != 1 {
941			t.Fatalf("newer recovery: %+v", r)
942		}
943		// The next selection uses the newly accepted record (sequence 10), not
944		// anything from the rejected reports.
945		if r := got.Results[7]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 10 || r.Revision != 1 {
946			t.Fatalf("select after accepted recovery: %+v", r)
947		}
948		// Final list: healthy at sequence 10 with the old reason cleared.
949		if len(got.Services) != 1 || got.Services[0].Revision != 1 {
950			t.Fatalf("services: %+v", got.Services)
951		}
952		insts := got.Services[0].Instances
953		if len(insts) != 1 || insts[0].ID != "a" || insts[0].Health != "healthy" || insts[0].Sequence != 10 || insts[0].Reason != "" {
954			t.Fatalf("a should be healthy at sequence 10: %+v", insts)
